// WF-09 TagManager v2
// Chatwoot labels are a visual projection of backend ConversationState.
const conv = $('Code - Target Conv').item.json;
const syncCaller = conv.sync_caller || null;
const payload = $input.first().json?.payload;
const currentTags = Array.isArray(payload)
  ? payload.map(t => String(t || '').trim()).filter(Boolean)
  : [];
const currentUnique = [...new Set(currentTags)];

const BRAND_TAGS = ['kia', 'hyundai'];
const ORIGIN_TAGS = ['outbound', 'inbound'];
const ATTEMPT_TAGS = ['primer_contacto', 'segundo_contacto', 'tercer_contacto'];
const COMMERCIAL_TAGS = [
  'interesado', 'calificacion', 'cotizacion', 'objeciones', 'humano',
  'ganado', 'perdido', 'no_contactable', 'descartado'
];
const WINDOW_TAGS = ['ventana_abierta', 'ventana_cerrada'];
const PLAN_TAGS = ['plan_selected', 'plan_1_year', 'plan_2_year', 'plan_3_year'];

const CANONICAL_MANAGED = new Set([
  ...BRAND_TAGS,
  ...ORIGIN_TAGS,
  ...ATTEMPT_TAGS,
  ...COMMERCIAL_TAGS,
  ...WINDOW_TAGS,
  ...PLAN_TAGS,
]);

const DEPRECATED_MANAGED = new Set([
  'contacto-1', 'espera-1', 'contacto-2', 'espera-2', 'contacto-3', 'espera-3',
  'oferta-presentada', 'transferido-humano', 'oportunidad-perdida', 'no-contactable',
  'multi_vehicle', 'vehicle_selected',
  'window:open', 'window:expired', 'window:closed',
  'handoff', 'handoff-humano', 'handoff-human', 'transferido',
  'new_lead', 'new-lead', 'pendiente', 'contacted_1', 'contacted_2', 'contacted_3',
  'engaged', 'vehicle_selection', 'value_presented', 'quoted', 'objection',
  'handoff_human', 'won', 'lost', 'not_contactable', 'discarded',
  'contacto_1', 'contacto_2', 'contacto_3', 'espera_1', 'espera_2', 'espera_3',
  'interes_confirmado', 'seleccion_vehiculo', 'presentacion_solucion',
  'presentacion_beneficios', 'necesidad_identificada', 'calificacion_gps',
  'calificacion_problema', 'calificacion_decisor', 'calificacion_urgencia',
  'calificacion_completa', 'transferido_humano', 'oportunidad_perdida',
]);

function isManaged(tag) {
  return CANONICAL_MANAGED.has(tag)
    || DEPRECATED_MANAGED.has(tag)
    || String(tag || '').startsWith('vehicle_');
}

function normalizeState(raw) {
  const key = String(raw || '').trim().toUpperCase();
  const aliases = {
    PENDIENTE: 'NEW_LEAD',
    CONTACTO_1: 'CONTACTED_1', ESPERA_1: 'CONTACTED_1', CONTACT_1_SENT: 'CONTACTED_1',
    CONTACTO_2: 'CONTACTED_2', ESPERA_2: 'CONTACTED_2', CONTACT_2_SENT: 'CONTACTED_2',
    CONTACTO_3: 'CONTACTED_3', ESPERA_3: 'CONTACTED_3', CONTACT_3_SENT: 'CONTACTED_3',
    INTERESADO: 'ENGAGED', INTERES_CONFIRMADO: 'ENGAGED', INTEREST_DETECTED: 'ENGAGED',
    SELECCION_VEHICULO: 'VEHICLE_SELECTION', CALIFICACION_VEHICULOS: 'VEHICLE_SELECTION',
    CALIFICACION: 'VALUE_PRESENTED', CALIFICACION_GPS: 'VALUE_PRESENTED',
    CALIFICACION_PROBLEMA: 'VALUE_PRESENTED', CALIFICACION_DECISOR: 'VALUE_PRESENTED',
    CALIFICACION_URGENCIA: 'VALUE_PRESENTED', CALIFICACION_COMPLETA: 'VALUE_PRESENTED',
    NECESIDAD_IDENTIFICADA: 'VALUE_PRESENTED', PRESENTACION_SOLUCION: 'VALUE_PRESENTED',
    PRESENTACION_BENEFICIOS: 'VALUE_PRESENTED', PRESENTAR_BENEFICIOS: 'VALUE_PRESENTED',
    COTIZACION: 'QUOTED', MOSTRAR_PRECIOS: 'QUOTED', PRICE_REQUESTED: 'QUOTED',
    PLAN_SELECCIONADO: 'PLAN_SELECTED',
    OBJECIONES: 'OBJECTION', ESPERAR_PREGUNTA: 'OBJECTION',
    TRANSFERIDO_HUMANO: 'HANDOFF_HUMAN', TRANSFERIR_ASESOR: 'HANDOFF_HUMAN',
    HANDOFF_DESCUENTO: 'HANDOFF_HUMAN', HUMAN_HANDOFF: 'HANDOFF_HUMAN',
    GANADO: 'WON', CIERRE: 'WON', CLOSED_WON: 'WON',
    OPORTUNIDAD_PERDIDA: 'LOST', PERDIDO: 'LOST', CLOSED_LOST: 'LOST',
    NO_CONTACTABLE: 'NOT_CONTACTABLE',
    DESCARTADO: 'DISCARDED',
  };
  return aliases[key] || key;
}

function parseJsonMaybe(value) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch (e) { return null; }
}

function slugVehicle(model) {
  const slug = String(model || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return slug ? 'vehicle_' + slug : null;
}

function slugPlan(plan) {
  const key = String(plan || '').trim().toUpperCase();
  const map = {
    PLAN_1_YEAR: 'plan_1_year', PLAN_2_YEAR: 'plan_2_year', PLAN_3_YEAR: 'plan_3_year',
    '1': 'plan_1_year', '2': 'plan_2_year', '3': 'plan_3_year',
    '12': 'plan_1_year', '24': 'plan_2_year', '36': 'plan_3_year',
  };
  return map[key] || null;
}

function categoryTags(tags, category) {
  const sets = {
    brand: BRAND_TAGS,
    origin: ORIGIN_TAGS,
    attempt: ATTEMPT_TAGS,
    commercial_state: COMMERCIAL_TAGS,
    window: WINDOW_TAGS,
    plan: PLAN_TAGS,
    vehicle: tags.filter(t => String(t || '').startsWith('vehicle_')),
  };
  if (category === 'vehicle') return sets.vehicle || [];
  const allowed = new Set(sets[category] || []);
  return tags.filter(t => allowed.has(t));
}

const desired = [];
function add(tag) {
  if (tag && !desired.includes(tag)) desired.push(tag);
}

const estadoRaw = String(conv.estado || '').trim();
const estado = normalizeState(estadoRaw);
const marca = String(conv.marca || '').trim().toUpperCase();
const source = String(conv.source || conv.origen || 'outbound').trim().toLowerCase();
const windowEval = parseJsonMaybe(conv.window_eval);
const attemptsDone = Number(conv.intentos_realizados || 0);
const validationErrors = [];

if (marca === 'KIA') add('kia');
else if (marca === 'HYUNDAI') add('hyundai');
else validationErrors.push({ code: 'MISSING_OR_INVALID_BRAND', value: conv.marca || null });

add(source.startsWith('inbound') ? 'inbound' : 'outbound');

const terminalCommercialStates = new Set(['HANDOFF_HUMAN', 'WON', 'LOST', 'NOT_CONTACTABLE', 'DISCARDED']);
const ATTEMPT_BY_STATE = {
  CONTACTED_1: 'primer_contacto',
  CONTACTED_2: 'segundo_contacto',
  CONTACTED_3: 'tercer_contacto',
};
let attemptTag = terminalCommercialStates.has(estado) ? null : ATTEMPT_BY_STATE[estado];
if (!attemptTag && !terminalCommercialStates.has(estado) && attemptsDone > 0) {
  if (attemptsDone >= 3) attemptTag = 'tercer_contacto';
  else if (attemptsDone === 2) attemptTag = 'segundo_contacto';
  else attemptTag = 'primer_contacto';
}
add(attemptTag);

const selectedPlan = conv.selected_plan || null;
const selectedPlanTag = slugPlan(selectedPlan || conv.selected_plan_duration);

const COMMERCIAL_BY_STATE = {
  ENGAGED: 'interesado',
  VEHICLE_SELECTION: 'calificacion',
  VALUE_PRESENTED: 'calificacion',
  QUOTED: 'cotizacion',
  PLAN_SELECTED: 'cotizacion',
  OBJECTION: 'objeciones',
  HANDOFF_HUMAN: 'humano',
  WON: 'ganado',
  LOST: 'perdido',
  NOT_CONTACTABLE: 'no_contactable',
  DISCARDED: 'descartado',
};
let commercialTag = COMMERCIAL_BY_STATE[estado];
if (selectedPlan && !terminalCommercialStates.has(estado)) commercialTag = 'cotizacion';
add(commercialTag);

if (!COMMERCIAL_BY_STATE[estado] && !ATTEMPT_BY_STATE[estado] && estado !== 'NEW_LEAD') {
  validationErrors.push({ code: 'UNMAPPED_STATE', value: estadoRaw || null, normalized: estado });
}

if (estado === 'PLAN_SELECTED' || selectedPlan) add('plan_selected');
if (selectedPlanTag) add(selectedPlanTag);

const activeVehicleTag = slugVehicle(conv.active_model);
if (activeVehicleTag) add(activeVehicleTag);

let windowActive = null;
if (typeof windowEval?.window_active === 'boolean') windowActive = windowEval.window_active;
else if (typeof windowEval?.window_expired === 'boolean') windowActive = !windowEval.window_expired;
else if (conv.last_inbound_message_at) windowActive = true;
else if (currentUnique.includes('ventana_abierta') || currentUnique.includes('window:open')) windowActive = true;
else windowActive = false;
add(windowActive ? 'ventana_abierta' : 'ventana_cerrada');

const externalTags = currentUnique.filter(tag => !isManaged(tag));
const desiredManaged = [...new Set(desired)];
const newTags = [...new Set([...externalTags, ...desiredManaged])];

const desiredSet = new Set(newTags);
const currentSet = new Set(currentUnique);
const added = newTags.filter(tag => !currentSet.has(tag));
const removed = currentUnique.filter(tag => !desiredSet.has(tag));
const deprecatedFound = currentUnique.filter(tag => DEPRECATED_MANAGED.has(tag));
const managedRemoved = currentUnique.filter(tag => isManaged(tag) && !desiredManaged.includes(tag));
const corrections = [];

for (const category of ['brand', 'origin', 'attempt', 'commercial_state', 'window', 'plan', 'vehicle']) {
  const before = categoryTags(currentUnique, category);
  const after = categoryTags(desiredManaged, category);
  if (before.length > 1 || before.sort().join(',') !== after.sort().join(',')) {
    corrections.push({ category, before, after });
  }
}
if (deprecatedFound.length) corrections.push({ category: 'deprecated', before: deprecatedFound, after: [] });
if (managedRemoved.length) corrections.push({ category: 'managed_removed', before: managedRemoved, after: [] });

const currentSorted = [...currentUnique].sort().join(',');
const newSorted = [...newTags].sort().join(',');
const changed = currentSorted !== newSorted;

const logEntry = {
  event: 'TAG_CHANGE',
  conversation_id: conv.conv_id,
  chatwoot_conv_id: conv.chatwoot_conv_id,
  before: currentUnique,
  after: newTags,
  added,
  removed,
  reason: 'SYNC_FROM_CONVERSATION_STATE',
  actor: 'WF-09',
  source_of_truth: 'ConversationState',
  state: estado,
  raw_state: estadoRaw,
  brand: marca || null,
  origin: source.startsWith('inbound') ? 'inbound' : 'outbound',
  window: windowActive ? 'ventana_abierta' : 'ventana_cerrada',
  selected_plan: selectedPlan,
  active_vehicle: conv.active_model || null,
  intentos_realizados: attemptsDone,
  corrections,
  validation_errors: validationErrors,
  preserved_external: externalTags,
  sync_source: conv.sync_source || 'cron',
  sync_caller: syncCaller,
  timestamp: new Date().toISOString(),
};

if (changed) console.log(JSON.stringify(logEntry));

return [{
  json: {
    conv_id: conv.conv_id,
    chatwoot_conv_id: conv.chatwoot_conv_id,
    sync_source: conv.sync_source || 'cron',
    sync_caller: syncCaller,
    new_tags: newTags,
    labels_body: JSON.stringify({ labels: newTags }),
    chatwoot_contact_id: conv.chatwoot_contact_id,
    contact_attrs_body: JSON.stringify({
      additional_attributes: Object.fromEntries(Object.entries({
        marca: marca || undefined,
        modelo: conv.active_model || conv.modelo || undefined,
        quicklink_id: conv.quicklink_id || undefined,
        estado_cris: estado || undefined,
      }).filter(([, value]) => value !== undefined && value !== null && String(value) !== ''))
    }),
    changed,
    event_type: 'tag_change',
    evento_payload: JSON.stringify(logEntry).replace(/'/g, "''"),
    estado,
    marca,
    origin: source.startsWith('inbound') ? 'inbound' : 'outbound',
    validation_errors: validationErrors,
    corrections,
  },
}];

const item = $input.first().json || {};
const body = item.body || item || {};
const rawConvId = String(body.conv_id || body.conversation_id || '').trim();
const rawChatwootConvId = String(body.chatwoot_conv_id || body.chatwoot_conversation_id || body.conversation?.id || '').trim();
const syncCaller = String(body.source || body.sync_caller || body.sync_reason || '').trim();
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const requestedConvId = UUID_REGEX.test(rawConvId) ? rawConvId : null;
const requestedChatwootConvId = /^\d+$/.test(rawChatwootConvId) ? rawChatwootConvId : null;

return [{
  json: {
    ...item,
    requested_conv_id: requestedConvId,
    requested_chatwoot_conv_id: requestedChatwootConvId,
    sync_source: 'webhook',
    sync_caller: syncCaller || null,
  },
}];

const item = $input.first().json || {};
let syncSource = item.sync_source || 'cron';
let syncCaller = item.sync_caller || null;
try {
  const req = $('Code - Normalize Sync Request').first().json;
  if (req?.sync_source) syncSource = req.sync_source;
  if (req?.sync_caller) syncCaller = req.sync_caller;
} catch (e) {}

return [{
  json: {
    ...item,
    sync_source: syncSource,
    sync_caller: syncCaller,
  },
}];

let computed = {};
try { computed = $('Code - Compute Tags').item.json || {}; } catch (e) {}
const changed = computed.changed === true;
return [{
  json: {
    success: true,
    sync_status: changed ? 'labels_updated' : 'labels_unchanged',
    sync_source: computed.sync_source || 'cron',
    sync_caller: computed.sync_caller || null,
    conv_id: computed.conv_id || null,
    chatwoot_conv_id: computed.chatwoot_conv_id || null,
    changed,
    new_tags: computed.new_tags || [],
    validation_errors: computed.validation_errors || [],
    corrections: computed.corrections || [],
  },
}];

let target = {};
try { target = $('Code - Target Conv').item.json || {}; } catch (e) {}
const err = $input.first().json || {};
return [{
  json: {
    success: false,
    sync_status: 'labels_get_failed',
    sync_source: target.sync_source || 'cron',
    sync_caller: target.sync_caller || null,
    conv_id: target.conv_id || null,
    chatwoot_conv_id: target.chatwoot_conv_id || null,
    error: err.error?.message || err.message || err.error || 'get_labels_failed',
  },
}];

const target = $input.first().json || {};
return [{
  json: {
    success: false,
    sync_status: 'target_not_found',
    sync_source: target.sync_source || 'webhook',
    sync_caller: target.sync_caller || null,
    conv_id: target.conv_id || null,
    chatwoot_conv_id: target.chatwoot_conv_id || null,
    error: 'target_conversation_not_found',
  },
}];

const data = $getWorkflowStaticData('global');
const now = Date.now();
const ttlMs = 10 * 60 * 1000;
const until = Number(data.cris06_cron_lock_until || 0);
if (until && until > now) {
  return [];
}
data.cris06_cron_lock_until = now + ttlMs;
data.cris06_cron_lock_started_at = new Date(now).toISOString();
return $input.all().map(item => ({ json: { ...(item.json || {}), sync_source: 'cron', cron_lock_acquired: true } }));

const data = $getWorkflowStaticData('global');
delete data.cris06_cron_lock_until;
data.cris06_cron_lock_released_at = new Date().toISOString();
return [{ json: { success: true, sync_status: 'cron_finished', sync_source: 'cron' } }];
